def pasar_a_la_planilla(apps, schema_editor):
    """Tema y observaciones pasan a "Datos de la capacitación" (el tema queda como primer renglón)
    y "Aspirantes" se abre en los dos destinos de la planilla."""
    Capacitacion = apps.get_model("partes", "Capacitacion")
    for c in Capacitacion.objects.all():
        c.datos = "\n".join(t for t in (c.tema, c.observaciones) if t)
        c.destinos = ",".join("aspirantes_1,aspirantes_2" if d == "aspirantes" else d
                              for d in c.destinos.split(",") if d)
        c.save(update_fields=["datos", "destinos"])



